def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: a serializable representation of the point, typically a dict
             with 'type': 'Point' and 'coordinates': [x, y] or None if value is None.
    """
    def _to_float(v):
        try:
            return float(v)
        except Exception as exc:
            raise TypeError(f"Coordinate value {v!r} cannot be converted to float") from exc

    if value is None:
        return None

    # Handle dicts with 'x', 'y' keys
    if isinstance(value, dict):
        if "x" in value and "y" in value:
            x, y = value["x"], value["y"]
            return {"type": "Point", "coordinates": [_to_float(x), _to_float(y)]}

    # Handle tuples/lists of length 2
    if isinstance(value, (list, tuple)):
        if len(value) == 2:
            x, y = value
            return {"type": "Point", "coordinates": [_to_float(x), _to_float(y)]}

    # Try duck-typing: common attributes for point-like objects
    try:
        x = getattr(value, "x")
        y = getattr(value, "y")
        return {"type": "Point", "coordinates": [_to_float(x), _to_float(y)]}
    except AttributeError:
        pass

    # Some point libraries expose a 'coords' attribute or method
    try:
        coords = getattr(value, "coords")
        # In shapely, coords is an iterable yielding (x, y)
        if isinstance(coords, (list, tuple)):
            if len(coords) == 0:
                raise TypeError("coords iterable is empty")
            # If first element is a tuple of coords
            first = coords[0]
            if isinstance(first, (list, tuple)) and len(first) == 2:
                x, y = first
                return {"type": "Point", "coordinates": [_to_float(x), _to_float(y)]}
            # If iterable of numbers directly
            if len(coords) == 2:
                x, y = coords
                return {"type": "Point", "coordinates": [_to_float(x), _to_float(y)]}
        # If coords is a method
        if callable(coords):
            result = coords()
            if isinstance(result, (list, tuple)) and len(result) == 2:
                x, y = result[0]
                return {"type": "Point", "coordinates": [_to_float(x), _to_float(y)]}
    except Exception as exc:
        raise TypeError(f"Failed to dehydrate point from .coords: {exc}") from exc

    # If none of the above worked, raise an informative error
    raise TypeError(f"Unsupported point type: {type(value).__name__}")

