        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import concurrent.futures
    import os

    # Helper to run a single batch and return its returncode and output
    def _run_batch(batch: Sequence[str]) -> tuple[int, bytes]:
        args = tuple(cmd) + tuple(batch)
        # Prepare subprocess parameters
        run_kwargs = dict(
            capture_output=True,
            text=False,
            check=False,
            **kwargs,
        )
        # On platforms supporting pty, and if color requested,
        # we can attempt to set up a PTY using os.setsid for the child process.
        # This does not provide a full PTY but forces a new session which
        # is often enough for terminal color handling.
        if color:
            if hasattr(os, "setsid"):
                run_kwargs["preexec_fn"] = os.setsid
        try:
            result = subprocess.run(args, **run_kwargs)
            out = result.stdout
            if result.stderr:
                out += result.stderr
            return result.returncode, out
        except Exception as e:
            return -1, str(e).encode()

    # If there are no varargs, just run the command once
    if not varargs:
        return _run_batch(())

    # Build batches respecting the maximum command line length
    batches: list[list[str]] = []
    current_batch: list[str] = []
    current_len: int = sum(len(part) + 1 for part in cmd)  # include a space after cmd parts
    for arg in varargs:
