            current_batch = [arg]
            current_len = current_len = sum(len(part) + 1 for part in cmd) + arg_len
        else:
            current_batch.append(arg)
            current_len += arg_len
    if current_batch:
        batches.append(current_batch)

    # Execute batches concurrently up to target_concurrency
    results: list[tuple[int, bytes]] = []
    if target_concurrency <= 1:
        for batch in batches:
            results.append(_run_batch(batch))
    else:
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            future_to_batch = {executor.submit(_run_batch, batch): batch for batch in batches}
