def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version parsing which converts a version string into a tuple of integers.
    It splits the string on dots and attempts to convert each component to an integer.
    Non-numeric components are ignored. Leading 'v' or 'V' characters are discarded.
    Returns an empty tuple for empty or None input.
    """
    if not isinstance(s, str) or not s:
        return ()
    # Strip whitespace
    s = s.strip()
    # Remove leading 'v' or 'V'
    if s and (s[0] == 'v' or s[0] == 'V'):
        s = s[1:]
    parts = s.split('.')
    nums = []
    for part in parts:
        # Extract leading digits
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            try:
                nums.append(int(num_str))
            except ValueError:
                # Should not occur, but skip on error
                continue
    return tuple(nums)

