def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # If output not given, create a new list to hold normalized items
    if output is None:
        output = []

    # Helper to process a single item
    def _add_item(item):
        # If item is a tuple or list, expand its contents recursively
        if isinstance(item, (tuple, list)):
            for sub in item:
                _add_item(sub)
        else:
            output.append(item)

    # Guard against None sequence
    if sequence is None:
        return output

    # If sequence is string/bytes, treat it as a single item
    if isinstance(sequence, (str, bytes)):
        _add_item(sequence)
    else:
        # Try to iterate over sequence; if not iterable, treat as single item
        try:
            iter(sequence)
        except TypeError:
            _add_item(sequence)
        else:
            for elem in sequence:
                _add_item(elem)

