def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expressions for label keys and values (simplified for illustration).
    # Kubernetes labels keys: must be 63 characters max, alphanumeric, dashes, underscores, periods.
    _LABEL_KEY_REGEX = re.compile(r'^[A-Za-z0-9]([-A-Za-z0-9_.]{0,61}[A-Za-z0-9])?$')
    # Values can be empty, but here we enforce the same pattern for simplicity.
    _LABEL_VALUE_REGEX = re.compile(r'^[A-Za-z0-9]([-A-Za-z0-9_.]{0,61}[A-Za-z0-9])?$')

    errors = []

    def add_error(item, message):
        errors.append({repr(item): message})

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            add_error(key, 'expected string or bytes-like object')
        else:
            # Validate key format
            if not _LABEL_KEY_REGEX.match(key):
                add_error(key, f"Label key '{key}' does not match the regex [...]")

        # Validate value
        # If value is an iterable other than string/bytes, treat each element separately
        if isinstance(value, (list, tuple)):
            for item in value:
                if not isinstance(item, (str, bytes)):
                    add_error(item, 'expected string or bytes-like object')
                else:
                    if not _LABEL_VALUE_REGEX.match(item):
                        add_error(item, f"Label value '{item}' does not match the regex [...]")
        else:
            if not isinstance(value, (str, bytes)):
                add_error(value, 'expected string or bytes-like object')
            else:
                if not _LABEL_VALUE_REGEX.match(value):
                    add_error(value, f"Label value '{value}' does not match the regex [...]")

    if errors:
        # Assume ValidationError accepts a 'messages' keyword argument
        raise ValidationError(messages=errors)

