    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    try:
        # Ensure value is a string
        if not isinstance(value, str):
            raise ValidationError("Value must be a string.")

        # Empty string is not allowed
        if value == "":
            raise ValidationError("Value cannot be empty.")

        # Define a simple alphanumeric/underscore pattern (similar to \w+ in regex)
        for ch in value:
            if not (ch.isalnum() or ch == "_"):
                raise ValidationError(f"Invalid character '{ch}' in value.")

    except ValidationError:
        # Re-raise the ValidationError to preserve the original exception
        raise
    except Exception as exc:
        # Wrap any other exception in a ValidationError
        raise ValidationError(f"Error validating value: {exc}") from exc

