def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    try:
        if not isinstance(key, str):
            raise ValidationError("Key must be a string.")

        key = key.strip()
        if not key:
            raise ValidationError("Key cannot be empty.")

        # Key length between 3 and 30 characters
        if not (3 <= len(key) <= 30):
            raise ValidationError("Key must be between 3 and 30 characters long.")

        # Allowed characters: alphanumerics, underscore, hyphen
        allowed_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
        if any(ch not in allowed_chars for ch in key):
            raise ValidationError("Key contains invalid characters; only letters, digits, underscores, and hyphens are allowed.")
    except ValidationError:
        # Re-raise ValidationError without modification
        raise
    except Exception as e:
        # Any other unexpected errors are wrapped in ValidationError
        raise ValidationError(f"Error validating key: {e}") from e

