def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(
            f"Expected manifest_dict to be a dict, got {type(manifest_dict).__name__}"
        )

    schema = {}
    for key, value in manifest_dict.items():
        # If the value is a dictionary, recurse
        if isinstance(value, dict):
            # In the first level we want to preserve identifying fields in metadata
            if first_level and key == "metadata":
                meta_schema = {}
                for mk, mv in value.items():
                    if isinstance(mv, dict):
                        meta_schema[mk] = generate_default_observer_schema_dict(mv)
                    elif isinstance(mv, list):
                        meta_schema[mk] = generate_default_observer_schema_list(mv)
                    else:
                        # Preserve only "name" and "namespace" from the manifest,
                        # everything else becomes None
                        if mk in ("name", "namespace"):
                            meta_schema[mk] = mv
                        else:
                            meta_schema[mk] = None
                schema[key] = meta_schema
            else:
                schema[key] = generate_default_observer_schema_dict(value)
        # If the value is a list, delegate to the list helper
        elif isinstance(value, list):
            try:
                schema[key] = generate_default_observer_schema_list(value)
            except NameError:
                raise NameError(
                    "generate_default_observer_schema_list is required for list handling"
                )
        # For other primitive types we set to None, except some identifying fields
        # when we're at the top level.
        elif first_level and key in ("kind", "apiVersion"):
            schema[key] = value
        else:
            schema[key] = None

    return schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")
    result = {}
    # Identifying fields that should keep their original value when first_level is True
    id_fields = {"apiVersion", "kind", "metadata"}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recursively process nested dicts
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process list elements: keep dict or list structure, otherwise None
            processed_list = []
            for item in value:
                if isinstance(item, dict):
                    processed_list.append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    # Nested list handling (though unlikely in K8s manifests)
                    processed_item = []
                    for sub in item:
                        processed_item.append(None if not isinstance(sub, (dict, list)) else (
                            generate_default_observer_schema_dict(sub, first_level=False) if isinstance(sub, dict) else None))
                    processed_list.append(processed_item)
                else:
                    processed_list.append(None)
            result[key] = processed_list
        else:
            # For leaf nodes, keep original value if top level and the key is an identifying field
            if first_level and key in id_fields:
                result[key] = value
            else:
                result[key] = None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer schema dictionary from a Kubernetes manifest dictionary.

    For each key in ``manifest_dict`` this function recursively constructs a new
    dictionary. All keys that map to non‑list and non‑dict values are replaced by
    ``None``. When ``first_level`` is ``True`` the values of the resource‑identifying
    fields are copied verbatim instead of being replaced.

    Identifying fields are typically ``metadata``, ``kind`` and ``apiVersion``.
    They are kept unchanged to preserve the identity of the resource.

    Args:
        manifest_dict (dict): Partial or complete Kubernetes resource.
        first_level (bool, optional): Indicates whether this dictionary represents
            the top level of the observer schema.

    Returns:
        dict: A dictionary suitable for use as part of the default observer schema.

    Raises:
        TypeError: If ``manifest_dict`` is not a dictionary.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    identifying_keys = {"metadata", "kind", "apiVersion"}
    result = {}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Delegate list handling to the complementary function
            # If the complementary function is not available, fall back to None
            try:
                result[key] = generate_default_observer_schema_list(value)
            except NameError:
                result[key] = None
        else:
            if first_level and key in identifying_keys:
                result[key] = value
            else:
                result[key] = None

    return result

