    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    def _recurse(value, is_first):
        if isinstance(value, dict):
            result = {}
            for k, v in value.items():
                if isinstance(v, (dict, list)):
                    result[k] = _recurse(v, False)
                else:
                    result[k] = v if is_first else None
            return result
        elif isinstance(value, list):
            return [_recurse(elem, False) for elem in value]
        else:
            return value if is_first else None

    return _recurse(manifest_dict, first_level)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Helper recursive function
    def _update(target, schema, resp):
        if target is None or resp is None:
            return
        # If schema is a list of field names
        if isinstance(schema, list):
            # In the unlikely case schema is list of dicts with keys for nested schema.
            # We will try to deduce nested schema from resp if possible.
            items_to_check = schema
        elif isinstance(schema, dict):
            # dict where keys are field names and values are nested schemas
            items_to_check = schema.keys()
        else:
            # Unhandled schema type
            return
        for field in items_to_check:
            try:
                # Skip if no corresponding field in response
                if field not in resp:
                    continue
                # If field not yet present in target, initialize it
                if field not in target:
                    target[field] = resp[field]
                else:
                    # If field is nested dict/list, recurse
                    sub_schema = None
                    if isinstance(schema, dict):
                        sub_schema = schema.get(field)
                    if isinstance(target[field], dict) and isinstance(resp[field], dict):
                        _update(target[field], sub_schema, resp[field])
                    elif isinstance(target[field], list) and isinstance(resp[field], list):
                        # For lists, we perform element-wise update if elements are dicts
                        # Assume schema for list items is sub_schema
                        if sub_schema:
                            for idx, item in enumerate(resp[field]):
                                if idx < len(target[field]):
                                    if isinstance(item, dict) and isinstance(target[field][idx], dict):
                                        _update(target[field][idx], sub_schema, item)
                                else:
                                    # append new item if not existing
                                    target[field].append(item)
                    # else if not complex type, keep existing value
            except Exception:
                # Silently skip problematic entries to avoid breaking entire update
                continue

    try:
        if not isinstance(last_applied_manifest, dict):
            # Ensure we are working on a dict; if not, convert (unlikely)
            return
        _update(last_applied_manifest, observer_schema, response)
    except Exception:
        # Basic fail-safe: do nothing if something goes wrong
        pass

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present.

    """
    try:
        # Standard case: everything is a list that aligns by index
        if isinstance(last_applied_manifest, list) and isinstance(observer_schema, list) and isinstance(
            response, list
        ):
            for idx, schema_item in enumerate(observer_schema):
                if not isinstance(schema_item, dict):
                    continue
                # Skip if no corresponding response value
                if idx >= len(response):
                    continue
                resp_val = response[idx]

                # Ensure the target list has a slot at idx
                while len(last_applied_manifest) <= idx:
                    last_applied_manifest.append(None)

                # Nested dict
                if isinstance(resp_val, dict):
                    if not isinstance(last_applied_manifest[idx], dict):
                        last_applied_manifest[idx] = {}
                    sub_schema = schema_item.get("sub_schema", [])
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[idx], sub_schema, resp_val
                    )
                    continue

                # Nested list
                if isinstance(resp_val, list):
                    if not isinstance(last_applied_manifest[idx], list):
                        last_applied_manifest[idx] = []
                    sub_schema = schema_item.get("sub_schema", [])
                    # Ensure sub-items exist
                    while len(last_applied_manifest[idx]) < len(resp_val):
                        last_applied_manifest[idx].append({})
                    for sub_idx, sub_val in enumerate(resp_val):
                        if isinstance(sub_val, dict):
                            update_last_applied_manifest_dict_from_resp(
                                last_applied_manifest[idx][sub_idx],
                                sub_schema,
                                sub_val,
                            )
                        else:
                            # Primitive sub‑value
                            last_applied_manifest[idx][sub_idx] = sub_val
                    continue

                # Primitive value
                if last_applied_manifest[idx] is None:
                    last_applied_manifest[idx] = resp_val

        # Fallback: treat as a mapping keyed by field names
        else:
            if not isinstance(observer_schema, list):
                return
            for schema_item in observer_schema:
                if not isinstance(schema_item, dict):
                    continue
                field_name = schema_item.get("field")
                if not field_name:
                    continue
                # If the field already exists, skip
                if field_name in last_applied_manifest:
                    continue
                if isinstance(response, dict) and field_name in response:
                    last_applied_manifest[field_name] = response[field_name]
                elif "default" in schema_item:
                    last_applied_manifest[field_name] = schema_item["default"]
    except Exception:
        # In a production setting you might want to log this error;
        # for the purposes of resilience, silently absorb unexpected issues.
        pass

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively update a partial list `last_applied_manifest` from a partial
    Kubernetes list `response` based on the provided `observer_schema`.

    Parameters
    ----------
    last_applied_manifest : list
        The list to be updated. It may be shorter than `response` or contain
        ``None`` placeholders. The list is modified in place.
    observer_schema : list
        Schema information describing the structure of list elements. It is
        passed unchanged to the recursive dictionary routine when a list
        element is a dictionary.
    response : list
        The source data from the Kubernetes API. This function will copy
        missing or placeholder elements from `response` into
        `last_applied_manifest`.

    Notes
    -----
    * If an element in ``response`` is a dictionary, the
      :func:`update_last_applied_manifest_dict_from_resp` routine is called
      to merge it into the corresponding element of ``last_applied_manifest``.
      The same function is called recursively for nested lists.
    * Scalar elements are copied directly when the target element is missing
      or ``None``.
    """
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest)}"
        )
    if not isinstance(response, list):
        raise TypeError(
            f"response must be a list, got {type(response)}"
        )
    if observer_schema is None:
        # If no schema is provided, perform a simple copy of missing values
        observer_schema = {}

    # Iterate over the source response list
    for idx, item in enumerate(response):
        # Ensure the target list has an element at this index
        try:
            target = last_applied_manifest[idx]
        except IndexError:
            # Create a placeholder based on the type of the source item
            if isinstance(item, dict):
                target = {}
            elif isinstance(item, list):
                target = []
            else:
                target = None
            last_applied_manifest.append(target)
        # If the target is None or explicitly missing, replace it
        if target is None:
            if isinstance(item, dict):
                target = {}
            elif isinstance(item, list):
                target = []
            else:
                target = item
            last_applied_manifest[idx] = target
            target = last_applied_manifest[idx]
        # Merge nested structures
        try:
            if isinstance(item, dict) and isinstance(target, dict):
                # Import here to avoid circular dependency if the dict function is
                # defined elsewhere
                update_last_applied_manifest_dict_from_resp(
                    target, observer_schema, item
                )
            elif isinstance(item, list) and isinstance(target, list):
                update_last_applied_manifest_list_from_resp(
                    target, observer_schema, item
                )
            else:
                # For scalars, set only if target is None (should be covered above)
                last_applied_manifest[idx] = item
        except Exception as exc:
            # Preserve state while reporting the issue
            raise RuntimeError(
                f"Failed to update list element at index {idx}: {exc}"
            ) from exc
    # If the target list is longer than the source, truncate the extras
    if len(last_applied_manifest) > len(response):
        del last_applied_manifest[len(response) :]

