    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: The dictionary of default observer schemas, keyed by resource kind.
    """
    # Validate input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    # Try to get the manifest list
    try:
        manifest = getattr(app.spec, "manifest", None)
    except AttributeError as exc:
        raise ValueError("The application object does not have a 'spec.manifest' attribute.") from exc

    if manifest is None:
        raise ValueError("app.spec.manifest is missing or None.")
    # The manifest is expected to be an iterable of resource dicts
    if not hasattr(manifest, "__iter__"):
        raise ValueError("app.spec.manifest should be an iterable of resource definitions.")

    # Retrieve any user‑defined observer schemas; assume a dict of the form {kind: schema}.
    try:
        custom_schemas = getattr(app.spec, "observer_schemas", {})
        if custom_schemas is None:
            custom_schemas = {}
        if not isinstance(custom_schemas, dict):
            # If it is not a dict, try to convert it into one
            custom_schemas = dict(custom_schemas)
    except Exception:
        custom_schemas = {}

    # Prepare the container for default schemas
    default_schemas = {}

    # Iterate over the manifest resources and build default entries when needed
    for res in manifest:
        # Each resource definition is expected to be a mapping with at least a 'kind' key
        try:
            kind = res["kind"]
        except Exception:
            # If the resource object does not contain a 'kind', ignore it
            continue

        # Skip resources that already have a custom observer schema
        if kind in custom_schemas:
            continue

        # Construct a very generic default schema.
        # This can be adjusted according to the real system requirements.
        # The default schema observes the most common fields that are present
        # on all Kubernetes objects: apiVersion, kind, metadata.name, metadata.namespace,
        # and status.phase if it exists.
        default_schema = {
            "observe": [
                "apiVersion",
                "kind",
                "metadata.name",
                "metadata.namespace"
            ]
        }
        # Attempt to add status.phase if the resource definition contains a status field
        try:
            if "status" in res and isinstance(res["status"], dict) and "phase" in res["status"]:
                default_schema["observe"].append("status.phase")
        except Exception:
            pass

        default_schemas[kind] = default_schema

    # Persist the default schemas back to the application spec for later use
    try:
        setattr(app.spec, "default_observer_schema", default_schemas)
    except Exception as exc:
        # If we cannot set the attribute, log an error and raise an exception
        raise RuntimeError("Failed to persist default observer schemas into app.spec.") from exc

    return default_schemas

