    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import json

    # Helper to determine if we are dealing with a pyfs root
    def is_pyfs_root(obj):
        # pyfilesystem root typically has .listdir and .remove methods
        return hasattr(obj, "listdir") or hasattr(obj, "walk")

    # If path is a filesystem path string or pathlib.Path
    if isinstance(path, str) or hasattr(path, "as_posix") or isinstance(path, bytes):
        try:
            p = os.path.abspath(path)
            if not os.path.isdir(p):
                return False
            comp_dir = p
        except Exception:
            return False
    # If path is a pyfs-like object
    elif is_pyfs_root(path):
        try:
            # Attempt to locate the .ocfl-info file from the root
            # Try listing root contents
            root_contents = []
            try:
                # pyfilesystem
                root_contents = list(path.listdir("."))
            except Exception:
                try:
                    root_contents = list(path.walk("."))
                except Exception:
                    pass
            # Look for .ocfl-info entry
            has_info = any(entry == ".ocfl-info" for entry in root_contents)
            if not has_info:
                return False
            # read the file
            info_data = path.open(".ocfl-info", "r").read()
        except Exception:
            return False
    else:
        # Unsupported path type
        return False

    # If we are dealing with a normal path, read .ocfl-info
    if not isinstance(path, str) and not hasattr(path, "open"):
        try:
            ocfl_file = os.path.join(comp_dir, ".ocfl-info")
            if not os.path.isfile(ocfl_file):
