    """
    Validate that all digests required by the caller are present in the
    manifest and that every digest in the manifest is actually used.

    Parameters
    ----------
    manifest_files : Mapping or Iterable
        Collection that maps file identifiers to manifest entries.  A
        manifest entry may be a dictionary containing a ``digest`` (single
        value) or ``digests`` (iterable) key, or it may be a raw digest
        string.
    digests_used : Iterable
        Iterable of digest strings that are required by the caller.

    Raises
    ------
    ValueError
        If any required digest is missing from the manifest or if the
        manifest contains digests that are not listed as used.
    """
    # Normalise the inputs to sets for membership tests.
    try:
        used_set = set(digests_used) if digests_used is not None else set()
    except TypeError:
        # If digests_used is not iterable, treat it as a single digest.
        used_set = {digests_used}

    present_set = set()

    if manifest_files is None:
        manifest_items = []
    else:
        # Accept both Mapping and generic iterable of key/value pairs.
        if hasattr(manifest_files, "items"):
            manifest_items = list(manifest_files.items())
        else:
            try:
                manifest_items = list(manifest_files)
            except TypeError:
                raise TypeError(
                    "manifest_files must be a mapping or iterable of items"
                )

    for key, entry in manifest_items:
        if isinstance(entry, dict):
            # Look for 'digests' first (list/tuple/set), then 'digest'.
            if "digests" in entry:
                digests = entry["digests"]
                if isinstance(digests, (list, tuple, set)):
                    present_set.update(digests)
                else:
                    present_set.add(digests)
            elif "digest" in entry:
                present_set.add(entry["digest"])
        else:
            # Assume the entry itself is a digest string.
            present_set.add(entry)

    missing_in_manifest = used_set - present_set
    unused_in_manifest = present_set - used_set

    errors = []
    if missing_in_manifest:
        errors.append(
            f"Required digests missing from manifest: {sorted(missing_in_manifest)}"
        )
    if unused_in_manifest:
        errors.append(
            f"Digests present in manifest but not used: {sorted(unused_in_manifest)}"
        )

    if errors:
        raise ValueError("; ".join(errors))

