def validate_as_prior_version(self, prior):
        """
        Confirm that *prior* represents an earlier state of the same inventory object.

        Parameters
        ----------
        prior : InventoryValidator
            The candidate prior version.

        Returns
        -------
        bool
            ``True`` if *prior* is a valid older version of ``self``.

        Raises
        ------
        TypeError
            If *prior* is not an InventoryValidator instance.
        ValueError
            If *prior* does not represent a prior version of ``self``.
        """
        # type check
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator instance")

        # Ensure we are not comparing the same object
        if self is prior:
            raise ValueError("prior cannot be the same instance as self")

        # Helper to safely get attribute, otherwise raise
        def _get_attr(obj, name, obj_name):
            try:
                return getattr(obj, name)
            except AttributeError:
                raise ValueError(
                    f"Object '{obj_name}' missing required attribute '{name}' "
                    "necessary for version comparison"
                )

        # Determine identifiers that must match
        inv_id = _get_attr(self, "inventory_id", "self")
        prior_id = _get_attr(prior, "inventory_id", "prior")
        if inv_id != prior_id:
            raise ValueError(
                f"inventory_id mismatch: self={inv_id} vs prior={prior_id}"
            )

        # Determine comparison vectors
        # Prefer a 'version' number if present
        try:
            self_version = getattr(self, "version")
            prior_version = getattr(prior, "version")
            if not isinstance(self_version, (int, float)):
                raise TypeError
            if not isinstance(prior_version, (int, float)):
                raise TypeError
            if prior_version >= self_version:
                raise ValueError(
                    f"prior version {prior_version} is not older than self {self_version}"
                )
            return True
        except (AttributeError, TypeError):
            pass  # fallback to timestamps

        try:
            self_ts = getattr(self, "last_updated")
            prior_ts = getattr(prior, "last_updated")
            # Coerce to comparable numeric/datetime
            if hasattr(self_ts, "timestamp"):
                self_ts = self_ts.timestamp()
            if hasattr(prior_ts, "timestamp"):
                prior_ts = prior_ts.timestamp()
            if not (isinstance(self_ts, (int, float)) and isinstance(prior_ts, (int, float))):
                raise TypeError
            if prior_ts >= self_ts:
                raise ValueError(
                    f"prior timestamp {prior_ts} is not older than self {self_ts}"
                )
            return True
        except (AttributeError, TypeError):
            pass  # No meaningful ordering information available

        # If we get here, we cannot determine a prior relationship
        raise ValueError(
            "Unable to determine that prior is a prior version of self "
            "(missing or incompatible 'version' or 'last_updated' attributes)."
        )

