def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation of inputs
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    # Convert version to a consistent type for comparison
    target_ver = version
    # Helper to determine if two versions are equal
    def ver_eq(a, b):
        try:
            return type(a) is type(b) and a == b
        except Exception:
            return False
    # Helper to determine if a version is greater than the target
    def ver_gt(a, b):
        try:
            # Try numeric comparison
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return a > b
        except Exception:
            pass
        # Fallback: string comparison
        try:
            return str(a) > str(b)
        except Exception:
            return False
    result = {}
    for logical_path, ver_map in inventory.items():
        if not isinstance(ver_map, dict):
            # Skip entries that don't map versions to files
            continue
        files = set()
        for ver, file_path in ver_map.items():
            try:
