def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    try:
        if not isinstance(fixity, dict):
            raise TypeError("The 'fixity' argument must be a dictionary.")
        if "files" not in fixity:
            raise KeyError("The fixity block must contain a 'files' key.")
        files_dict = fixity["files"]
        if not isinstance(files_dict, dict):
            raise TypeError("The 'files' entry in the fixity block must be a dictionary.")

        if not isinstance(manifest_files, (list, set, tuple)):
            raise TypeError("The 'manifest_files' argument must be a list, set, or tuple.")
        manifest_set = set(manifest_files)

        for fname, checksum in files_dict.items():
            if fname not in manifest_set:
                raise ValueError(f"File '{fname}' referenced in fixity but not present in the manifest.")
            if not isinstance(checksum, str):
                raise TypeError(f"Checksum for file '{fname}' must be a string.")
            # Simple sanity check for checksum format: allow either raw hex or algo:hash
            if ":" in checksum:
                algo, val = checksum.split(":", 1)
                if not algo or not val:
                    raise ValueError(f"Checksum for file '{fname}' has an invalid format.")
                if len(val) == 0:
                    raise ValueError(f"Checksum value for file '{fname}' is empty.")
            else:
                if len(checksum) == 0:
                    raise ValueError(f"Checksum for file '{fname}' is empty.")

        return True
    except Exception as exc:
        # Re-raise the exception to let callers handle it as needed
        raise exc from None

