def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping of XML basename (without extension) to a list of relative file paths
        that share that basename (including the XML file itself). The list is sorted
        alphabetically.
    """
    import os

    # Validate input
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise ValueError(f"Folder '{folder}' does not exist or is not a directory")

    try:
        # First pass: collect all XML basenames
        xml_basenames = set()
        for root, _, files in os.walk(folder):
            for fname in files:
                if fname.lower().endswith('.xml'):
                    basename = os.path.splitext(fname)[0]
                    xml_basenames.add(basename)

        # If no XML files found, return empty dict
        if not xml_basenames:
            return {}

        # Initialize result dictionary
        result = {basename: [] for basename in xml_basenames}

        # Second pass: associate files with their XML basename
        for root, _, files in os.walk(folder):
            for fname in files:
                basename = os.path.splitext(fname)[0]
                if basename in xml_basenames:
                    # Build relative path
                    rel_path = os.path.relpath(os.path.join(root, fname), folder)
                    result[basename].append(rel_path)

        # Sort file lists for each basename
        for basename in result:
            result[basename].sort()
        return result

    except OSError as exc:
        # Handle filesystem errors gracefully
        raise RuntimeError(f"Error accessing folder '{folder}': {exc}") from exc

