def add_rendition(self, lang, file_path):
        """
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
        """
        # Validate inputs
        if not isinstance(lang, str) or not isinstance(file_path, str):
            raise ValueError("Both 'lang' and 'file_path' must be strings")

        try:
            # Extract the base filename
            parts = file_path.replace("\\", "/").split("/")
            basename = parts[-1]

            # Separate the name and extension
            if "." in basename:
                name_part, ext = basename.rsplit(".", 1)
                ext = "." + ext
            else:
                name_part = basename
                ext = ""

            # Remove the language suffix if present
            suffix = f"-{lang}"
            if name_part.endswith(suffix):
                original_name_part = name_part[: -len(suffix)]
            else:
                original_name_part = name_part

            original_file = f"{original_name_part}{ext}"
        except Exception as exc:
            raise ValueError(f"Invalid file_path format: {exc}") from exc

        # Ensure the renditions dictionary exists
        if not hasattr(self, "renditions") or not isinstance(self.renditions, dict):
            self.renditions = {}

        # Retrieve or create the entry for the original file
        entry = self.renditions.get(original_file, {"original": original_file})
        entry[lang] = file_path
        self.renditions[original_file] = entry

        return None

