    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supr. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    Returns a tuple (number, suppl) where number is int or string (for ranges)
    and suppl is int or None.
    """
    import re
    try:
        text = getattr(issue, 'text', None)
        if text is None:
            # If issue is a string or has __str__ representation
            text = str(issue)
    except Exception:
        return (None, None)

    if not isinstance(text, str):
        return (None, None)

    text = text.strip()
    # Remove leading XML tags if present
    # Extract the content between <issue> tags if present
    m = re.search(r'<issue>(.*?)</issue>', text, flags=re.IGNORECASE | re.DOTALL)
    if m:
        content = m.group(1).strip()
    else:
        content = text

    # Find the first numeric value (possibly a range like 2-5)
    number = None
    number_match = re.match(r'^[\s]*([0-9]+(?:-[0-9]+)?)', content)
    if number_match:
        num_str = number_match.group(1)
        if '-' in num_str:
            number = num_str
        else:
            try:
                number = int(num_str)
            except ValueError:
                number = None

    # Find supplement value (suppl, supp, spe, s, suppr., etc.)
    suppl = None
    # Search for tokens indicating supplement
    sup_patterns = r'(?i)(suppl|supp|supp\.?|suppr\.?|spe|s)[\s\.\,\-]*([0-9]+(?:-[0-9]+)?)?'
    sup_match = re.search(sup_patterns, content)
    if sup_match:
        sup_num_str = sup_match.group(2)
        if sup_num_str:
            if '-' in sup_num_str:
                try:
                    # For ranges like "1-2", we return the first number
                    suppl = int(sup_num_str.split('-')[0])
                except Exception:
                    suppl = None
            else:
                try:
                    suppl = int(sup_num_str)
                except Exception:
                    suppl = None
        else:
            # No explicit number following the marker. We consider no supplement number.
            suppl = None

    return (number, suppl)

