def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    try:
        # Lower‑case and strip whitespace
        s = issue.strip().lower()

        # Remove parentheses and common punctuation
        for ch in ['(', ')', '.', ',']:
            s = s.replace(ch, ' ')

        # Split into tokens
        tokens = [t for t in s.split() if t]
        number = None
        suppl = None

        # Detect the main number (first numeric token or range)
        for idx, token in enumerate(tokens):
            # token might be a range like "2-5"
            if '-' in token:
                parts = token.split('-')
                if all(part.isdigit() for part in parts):
                    number = int(parts[0])
                    # Continue to look for supplement after this token
                    break
            if token.isdigit():
                number = int(token)
                break

        # Search for supplement indicators
        # Define short forms that may appear in the text
        sup_keywords = ('suppl', 'sup', 's', 'spe', 'supp')

        for idx, token in enumerate(tokens):
            # Exact keyword followed by a number
            if token in sup_keywords:
                if idx + 1 < len(tokens) and tokens[idx + 1].isdigit():
                    suppl = int(tokens[idx + 1])
                    break
                # Nothing follows, treat as a presence flag
                else:
                    # if there is no number after "s" or "spe", look in the same token
                    pass

            # Handle concatenated forms like "s2" or "spe2"
            for kw in sup_keywords:
                if token.startswith(kw) and len(token) > len(kw) and token[len(kw):].isdigit():
                    suppl = int(token[len(kw):])
                    break
            if suppl is not None:
                break

        return (number, suppl)
    except Exception:
        # In case of unexpected input, return None values
        return (None, None)

