def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    if not issue or not isinstance(issue, str):
        return None, None

    # Remove common surrounding punctuation and whitespace
    text = issue.strip().lstrip('<issue>').rstrip('</issue>').strip(',').strip()

    # Find number part (first integer or range such as 2-5)
    number = None
    num_match = re.match(r'^\D*?(\d+(?:-\d+)?)(?:\s|$)', text, re.IGNORECASE)
    if num_match:
        num_str = num_match.group(1)
        # If range like 2-5, take the first number
        if '-' in num_str:
            try:
                number = int(num_str.split('-', 1)[0])
            except ValueError:
                number = None
        else:
            try:
                number = int(num_str)
            except ValueError:
                number = None
        # remaining text after the number
        rest = text[num_match.end():].strip()
    else:
        rest = text

    # Find suppl part (keywords such as sup, suppl, supp, spe, sp, s)
    suppl = None
    # Pattern to capture optional keyword and optional number after it
    sup_pattern = re.compile(
        r'(?i)\b(?:suppl|supp|spe|sp|s)\b\.?\s*(\d+)?'
    )
    sup_match = sup_pattern.search(rest)
    if sup_match:
        sup_num = sup_match.group(1)
        if sup_num:
            try:
                suppl = int(sup_num)
            except ValueError:
                suppl = None
        else:
            # Keyword found but no following number
            suppl = None
    else:
        # Additionally handle cases like "spe2" or "spe.2" where number follows immediately
        alt_pattern = re.compile(r'(?i)\b(?:suppl|supp|spe|sp|s)(?:\.?\s*)(\d+)', re.IGNORECASE)
        alt_match = alt_pattern.search(rest)
        if alt_match:
            try:
                suppl = int(alt_match.group(1))
            except ValueError:
                suppl = None

    return number, suppl

