def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        The output includes the class name and all public attributes
        sorted alphabetically. If an attribute value has its own ``pretty``
        method, that method is invoked recursively with an increased indent.
        ``indent`` controls the level of whitespace indentation. ``debug``,
        if True, appends the type of each value after it.
        """
        try:
            # Validate parameters
            if not isinstance(indent, int) or indent < 0:
                indent = 0
            if not isinstance(debug, bool):
                debug = False

            # Helper for recursive rendering
            def _render(obj, level, seen):
                if id(obj) in seen:
                    return f"<recursion>"
                seen.add(id(obj))

                indent_str = " " * (level * 2)
                lines = []

                try:
                    cls_name = obj.__class__.__name__
                except Exception:
                    cls_name = str(type(obj))

                lines.append(f"{indent_str}{cls_name}:")

                # Gather attributes: decide between __dict__ and dir()
                attrs = {}
                try:
                    if hasattr(obj, "__dict__"):
                        attrs.update(obj.__dict__)
                    else:
                        for name in dir(obj):
                            if name.startswith("_"):
                                continue
                            try:
                                attrs[name] = getattr(obj, name)
                            except Exception:
                                attrs[name] = "<unavailable>"
                except Exception:
                    # fallback to empty dict
                    attrs = {}

                for key in sorted(attrs):
                    value = attrs[key]
                    next_level = level + 1
                    inner_indent = " " * (next_level * 2)
                    if hasattr(value, "pretty") and callable(value.pretty):
                        try:
                            val_str = value.pretty(indent=next_level, debug=debug)
                        except Exception:
                            val_str = f"<error pretty> {value!r}"
                    else:
                        # Stringify the value without recursion depth
                        val_str = repr(value)
                        if hasattr(value, "__dict__"):
                            # Try to represent nested objects succinctly
                            try:
                                if hasattr(value, "pretty"):
                                    val_str = value.pretty(indent=next_level, debug=debug)
                            except Exception:
                                val_str = repr(value)

                    if debug:
                        val_type = type(value).__name__
                        val_str += f" ({val_type})"

                    lines.append(f"{inner_indent}{key}: {val_str}")

                return "\n".join(lines)

            result = _render(self, indent, set())
            return result
        except Exception as e:
            # Return a readable error string rather than raising
            return f"<Error in pretty: {e!r}>"

