def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted, multiline string representation of ``self``.
    Nested objects are indented for readability.  Circular references
    are detected and shown as ``<Circular Reference>``.  The ``debug``
    flag adds type information for objects that expose ``__dict__``.
    """
    visited = set()

    def _pretty(obj, level):
        obj_id = id(obj)
        if obj_id in visited:
            return "<Circular Reference>"
        visited.add(obj_id)

        try:
            # Basic scalars
            if isinstance(obj, (str, int, float, bool, type(None))):
                return repr(obj)

            # Mapping types
            if isinstance(obj, dict):
                if not obj:
                    return "{}"
                lines = []
                for k in sorted(obj, key=lambda x: str(x)):
                    v = obj[k]
                    lines.append(
                        f"\n{' ' * ((level + 1) * 4)}{repr(k)}: {_pretty(v, level + 1)}"
                    )
                return "{" + ",".join(lines) + f"\n{' ' * (level * 4)}}"  

            # Sequence and set types
            if isinstance(obj, (list, tuple, set, frozenset)):
                type_name = type(obj).__name__
                if not obj:
                    return f"{type_name}()"
                lines = []
                for v in obj:
                    lines.append(
                        f"\n{' ' * ((level + 1) * 4)}{_pretty(v, level + 1)}"
                    )
                if isinstance(obj, list):
                    return "[" + ",".join(lines) + f"\n{' ' * (level * 4)}]"
                elif isinstance(obj, tuple):
                    return "(" + ",".join(lines) + f"\n{' ' * (level * 4)})"
                else:  # set or frozenset
                    return "{" + ",".join(lines) + f"\n{' ' * (level * 4)}}" 

            # Objects with a __dict__ (e.g., dataclasses or plain classes)
            if hasattr(obj, "__dict__"):
                attrs = []
                for name, val in sorted(obj.__dict__.items()):
                    attrs.append(
                        f"{name}={_pretty(val, level + 1)}"
                    )
                attrs_str = ", ".join(attrs)
                type_name = type(obj).__name__
                # Show type information when debug is enabled
                if debug:
                    return f"{type_name} {{ {attrs_str} }} (id={obj_id})"
                else:
                    return f"{type_name}({attrs_str})"

            # Fallback to repr
            return repr(obj)

        finally:
            visited.remove(obj_id)

    return _pretty(self, indent)

