def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def get_children(expr):
        # Attempt to fetch children from common attribute names
        if hasattr(expr, "args"):
            return list(expr.args)
        if hasattr(expr, "children"):
            return list(expr.children)
        return []

    def is_operator(expr, op):
        return (hasattr(expr, "operator") and expr.operator == op) or \
               (hasattr(expr, "op") and expr.op == op) or \
               (hasattr(expr, "func") and getattr(expr.func, "__name__", "") == op)

    def make_operator(orig, children):
        # Try to construct a new expression of the same type
        try:
            return orig.__class__(*children)
        except Exception:
            # Fallback: if orig has 'args' attribute, set it
            if hasattr(orig, "args"):
                obj = orig.__class__(*children)
                return obj
            # If cannot construct, return original (will show unchanged)
            return orig

    def _simplify(expr):
        # Base case: if expr is not an operator, return as is
        if not is_operator(expr, "&") and not is_operator(expr, "|") and not is_operator(expr, "~"):
            return expr

