def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate that the hook is hashable (so it can be used as a dict key)
    try:
        hash(hook)
    except Exception as exc:
        raise TypeError(f"The hook {hook!r} must be hashable") from exc

    def decorator(func):
        # Ensure the object being decorated is callable
        if not callable(func):
            raise TypeError("Decorator can only be applied to callable objects")
        # Lazily create the registry dictionary if it doesn't exist
        if not hasattr(self, "_registry"):
            try:
                self._registry = {}
            except Exception as exc:
                raise RuntimeError("Failed to initialize the registry attribute") from exc
        # Add the function to the list for this hook
        try:
            self._registry.setdefault(hook, []).append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register function {func.__name__} for hook {hook!r}") from exc
        # Return the original function unchanged
        return func

    return decorator
