    if not isinstance(etcd_host, str):
        raise TypeError(f"Expected 'etcd_host' to be a string, got {type(etcd_host).__name__}")
    if not isinstance(etcd_port, int):
        raise TypeError(f"Expected 'etcd_port' to be an integer, got {type(etcd_port).__name__}")
    if not (0 < etcd_port < 65536):
        raise ValueError(f"etcd_port must be between 1 and 65535, got {etcd_port}")

    # Build the configuration dictionary
    config = {
