import sys

def tzname_in_python2(namefunc):
    """Return a wrapper that converts Unicode outputs to bytestrings on Python 2."""
    _in_py2 = sys.version_info[0] == 2

    if _in_py2:
        # In Python 2, `unicode` type exists and `str` is a bytestring
        def wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            try:
                # `unicode` may not be defined if type was shadowed; catch NameError
                if isinstance(result, unicode):  # noqa: F821
                    try:
                        return result.encode('utf-8')
                    except Exception:
                        # Fallback in case of encoding errors
                        return result.encode('utf-8', 'replace')
            except NameError:
                # Should not happen, but just in case
                pass
            return result
    else:
        # In Python 3 the API already returns str, so no conversion needed
        def wrapper(*args, **kwargs):
            return namefunc(*args, **kwargs)

