def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : dict | list | tuple
        Information about the version. For a dict, it may contain the keys
        ``major``, ``minor``, ``patch``, ``pre`` and ``build``.  For a list or
        tuple, the first three elements are interpreted as major, minor and
        patch.  If a fourth element exists it is taken as the pre-release tag
        and a fifth element as the build metadata.
    style : str
        One of ``'full'``, ``'short'`` or ``'tiny'``.  ``'full'`` renders the
        complete semantic‑version string. ``'short'`` renders ``major.minor``.
        ``'tiny'`` renders only the major component.

    Returns
    -------
    str
        The formatted version string.

    Raises
    ------
    ValueError
        If required components are missing or the style is unknown.
    """
    # Helper to convert a value to a string or raise
    def _ensure_int(val, name):
        try:
            return int(val)
        except Exception:
            raise ValueError(f"Component '{name}' must be an integer. Got: {val!r}") from None

    major = minor = patch = None
    pre = build = None

    # Parse the pieces
    if isinstance(pieces, dict):
        for key in ("major", "minor", "patch", "pre", "build"):
            if key in pieces:
                if key in ("major", "minor", "patch"):
                    try:
                        setattr(locals(), key, _ensure_int(pieces[key], key))
                    except ReferenceError:
                        # locals() not writable; assign via globals()
                        globals()[key] = _ensure_int(pieces[key], key)
                else:
                    globals()[key] = str(pieces[key])
    elif isinstance(pieces, (list, tuple)):
        if len(pieces) < 3:
            raise ValueError("List/tuple must contain at least major, minor, and patch.")
        major = _ensure_int(pieces[0], "major")
        minor = _ensure_int(pieces[1], "minor")
        patch = _ensure_int(pieces[2], "patch")
        if len(pieces) >= 4:
            pre = str(pieces[3])
        if len(pieces) >= 5:
            build = str(pieces[4])
    else:
        raise TypeError("pieces must be a dict, list, or tuple.")

    # Validation of required components
    if major is None or minor is None or patch is None:
        raise ValueError("major, minor, and patch components are required.")

    # Construct the string based on style
    if style == "full":
        base = f"{major}.{minor}.{patch}"
        if pre:
            base += f"-{pre}"
        if build:
            base += f"+{build}"
        return base
    elif style == "short":
        return f"{major}.{minor}"
    elif style == "tiny":
        return str(major)
    else:
        raise ValueError(f"Unsupported style: {style!r}")

