def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Parameters
        ----------
        validate_objects : bool, optional
            If True, checks that each expected file is present.
        check_digests : bool, optional
            If True, verifies MD5 digests of files against stored expectations.
        show_warnings : bool, optional
            If True, prints warnings for missing files or digest mismatches.

        Returns
        -------
        tuple
            (num_objects, good_objects) where
            num_objects  : int, number of files encountered
            good_objects : int, number of files that passed all checks
        """
        # Validate types of the optional arguments
        if not isinstance(validate_objects, bool):
            raise TypeError("validate_objects must be a boolean")
        if not isinstance(check_digests, bool):
            raise TypeError("check_digests must be a boolean")
        if not isinstance(show_warnings, bool):
            raise TypeError("show_warnings must be a boolean")

        # Ensure that the instance has a root directory attribute
        if not hasattr(self, 'root_dir'):
            raise AttributeError("Instance lacks a 'root_dir' attribute required for hierarchy validation")

        root = self.root_dir

        if not isinstance(root, str):
            raise TypeError("self.root_dir must be a string path")

        # Check existence of the root directory
        try:
            if not os.path.isdir(root):
                if show_warnings:
                    print(f"Root path '{root}' does not exist or is not a directory.")
                return 0, 0
        except Exception as exc:
            if show_warnings:
                print(f"Error accessing root path '{root}': {exc}")
            return 0, 0

        num_objects = 0
        good_objects = 0

        # Optionally load expected digests map
        expected_digests = {}
        if check_digests and hasattr(self, 'expected_digests') \
           and isinstance(self.expected_digests, dict):
            expected_digests = self.expected_digests

        # Walk through the directory tree
        for dirpath, dirnames, filenames in os.walk(root, topdown=True, onerror=None):
            for filename in filenames:
                file_path = os.path.join(dirpath, filename)
                num_objects += 1

                # Validate object existence if required
                if validate_objects:
                    if not os.path.isfile(file_path):
                        if show_warnings:
                            print(f"Missing file: {file_path}")
                        continue

                # Validate digest if required
                good = True
                if check_digests:
                    expected = expected_digests.get(file_path)
                    if expected is not None:
                        try:
                            with open(file_path, 'rb') as fp:
                                data = fp.read()
                            actual = hashlib.md5(data).hexdigest()
                            if actual != expected:
                                if show_warnings:
                                    print(f"Digest mismatch for {file_path}:\n"
                                          f"  Expected: {expected}\n"
                                          f"  Actual  : {actual}")
                                good = False
                        except Exception as exc:
                            if show_warnings:
                                print(f"Error reading {file_path}: {exc}")
                            good = False
                    else:
                        # No expected digest provided; skip digest check
                        pass

                if good:
                    good_objects += 1

        return num_objects, good_objects

