def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Validate that the root path is set and is a string
    root_path = getattr(self, "root_path", None)
    if not isinstance(root_path, str) or not root_path:
        raise ValueError("`root_path` must be a non-empty string representing the storage root directory.")

    # Ensure the root directory exists
    try:
        import os
        if not os.path.isdir(root_path):
            os.makedirs(root_path, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Failed to create OCFL root directory '{root_path}': {exc}") from exc

    # Create the obligatory structure for an OCFL root
    # The spec requires a '.ocfl_root' file with a version number
    try:
        ocfl_root_path = os.path.join(root_path, ".ocfl_root")
        with open(ocfl_root_path, "w", encoding="utf-8") as f:
            f.write("OCFL_VERSION=1.0\n")
    except OSError as exc:
        raise RuntimeError(f"Failed to write .ocfl_root marker file: {exc}") from exc

    # Create default subdirectories if they don't already exist
    # Typically OCFL uses 'objects' under the root
    try:
        objects_dir = os.path.join(root_path, "objects")
        if not os.path.isdir(objects_dir):
            os.makedirs(objects_dir, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Failed to create objects directory '{objects_dir}': {exc}") from exc

    # Mark initialization as complete
    self._initialized = True
    return True  # indicate success.

