def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return None
    version = version.strip()
    if not version:
        return None

    # Split into components separated by '.'
    parts = version.split('.')
    # Work on the last component
    last = parts[-1]
    # Determine if last part consists only of digits
    if not last.isdigit():
        return None

    try:
        orig_num = int(last)
        new_num = orig_num + 1
    except Exception:
        return None

    # Preserve leading zero width if possible
    width = len(last)
    if new_num < 10 ** width:
        new_last = str(new_num).zfill(width)
    else:
        new_last = str(new_num)

    parts[-1] = new_last
    return '.'.join(parts)

