def deep_merge_nodes(nodes):
    '''
    Given a list of (ScalarNode, Node) tuples that represent
    a YAML mapping, merge any duplicate keys recursively.
    Duplicate scalar keys are compared using the key node's .value attribute.
    If two values corresponding to the same key are MappingNode instances, the
    function performs a deep merge of the mappings.  Otherwise, the value from
    the latter node wins.
    '''
    if not isinstance(nodes, list):
        return []

    merged_dict = {}
    order = []

    # Helper to deep merge two MappingNode instances
    def _merge_mapping(a, b):
        if not hasattr(a, 'tag') or not hasattr(b, 'tag'):
            # not mapping nodes; last wins
            return b

        # Preserve original order: start with a's order, then b's new entries
        result = []
        seen = {}

        # Build dict of a's children
        for kid, val in a.value:
            key = kid.value
            seen[key] = (kid, val)

        # Merge b's children
        for kid, val in b.value:
            key = kid.value
            if key in seen:
                old_kid, old_val = seen[key]
                if hasattr(old_val, 'tag') and hasattr(val, 'tag'):
                    merged_val = _merge_mapping(old_val, val)
                else:
                    merged_val = val
                seen[key] = (old_kid, merged_val)
            else:
                seen[key] = (kid, val)

        # Build ordered result list
        used = set()
        for kid, val in a.value:
            key = kid.value
            if key in seen:
                _, merged_val = seen[key]
                result.append((kid, merged_val))
                used.add(key)
        for kid, val in b.value:
            key = kid.value
            if key not in used:
                result.append((kid, val))
                used.add(key)

        return type(a)(a.tag, result)

    for key_node, value_node in nodes:
        if not hasattr(key_node, 'value'):
            continue
        key = key_node.value
        if key in merged_dict:
            _, existing_value = merged_dict[key]
            if hasattr(existing_value, 'tag') and hasattr(value_node, 'tag'):
                merged_value = _merge_mapping(existing_value, value_node)
            else:
                merged_value = value_node
            merged_dict[key] = (existing_value, merged_value)
        else:
            merged_dict[key] = (key_node, value_node)
            order.append(key)

    return [(merged_dict[k][0], merged_dict[k][1]) for k in order]

