def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Validate input types
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of argument strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to argparse.ArgumentParser instances")

    parsed_results = {}
    consumed_counter = {}

    # Helper to compute the Counter of arguments that were removed
    def _consumed_from(parser, args):
        _, remaining = parser.parse_known_args(args)
        from collections import Counter
        consumed = Counter(args) - Counter(remaining)
        return consumed

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Subparser '{name}' does not have parse_known_args method")
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_results[name] = namespace
            cons = _consumed_from(parser, unparsed_arguments)
            # Merge counts
            if consumed_counter:
                for k, v in cons.items():
                    consumed_counter[k] = consumed_counter.get(k, 0) + v
            else:
                consumed_counter = cons
        except Exception as e:
            # Preserve exception context but continue collecting others
            parsed_results[name] = None
            # We do not raise to allow other subparsers to be processed
            # Optionally, you could log or attach the exception to the namespace.

    # Compute remaining arguments not claimed by any subparser
    from collections import Counter
    original_counter = Counter(unparsed_arguments)
    remaining_counter = original_counter - Counter(consumed_counter)

    # Expand counter back to list preserving order as much as possible
    remaining_args = []
    for arg in unparsed_arguments:
        if remaining_counter[arg] > 0:
            remaining_args.append(arg)
