        Merged list of tuples with duplicate keys merged.

    Raises
    ------
    ValueError
        If input is not an iterable of 2-element tuples.
    """
    # Helper functions --------------------------------------------------------
    def _is_mapping_node(node):
        return hasattr(node, 'tag') and hasattr(node, 'value') and type(node).__name__ == 'MappingNode'

    def _is_scalar_node(node):
        return hasattr(node, 'tag') and hasattr(node, 'value') and type(node).__name__ == 'ScalarNode'

    def _merge_node_values(a, b):
        """
        Merge two nodes `a` and `b`. If both are MappingNode, perform deep merge;
        otherwise, return the second node (last wins).
        """
        try:
            if _is_mapping_node(a) and _is_mapping_node(b):
                return _merge_mapping_nodes(a, b)
            else:
                return b
        except Exception:
            # Fallback: last one wins
            return b

    def _merge_mapping_nodes(a_map, b_map):
        """
        Merge two MappingNodes assuming they contain tuples of (ScalarNode, node).
        Keys are compared by the ScalarNode.value.
        """
        merged_items = []

        # Build lookup for b
        b_lookup = {}
        if hasattr(b_map, 'value') and isinstance(b_map.value, list):
            for key_node, val_node in b_map.value:
                if not _is_scalar_node(key_node):
                    continue
                b_lookup[key_node.value] = (key_node, val_node)

        # Merge entries from a_map
        if hasattr(a_map, 'value') and isinstance(a_map.value, list):
            for key_node, val_node in a_map.value:
                key_str = key_node.value
                if key_str in b_lookup:
                    _, b_val_node = b_lookup[key_str]
                    merged_val = _merge_node_values(val_node, b_val_node)
                    merged_items.append((key_node, merged_val))
                    del b_lookup[key_str]  # remove to avoid re-adding below
                else:
                    merged_items.append((key_node, val_node))

        # Add remaining items from b_map that weren't in a_map
        for _, (key_node, val_node) in b_lookup.items():
            merged_items.append((key_node, val_node))

        # Return new MappingNode with same tag as a_map
        try:
            return type(a_map)(tag=a_map.tag, value=merged_items)
        except Exception:
            # If type constructor fails, fall back to a simple object
            return type(a_map)(tag=a_map.tag, value=merged_items)

    # Main merge logic ---------------------------------------------------------
    try:
        if not hasattr(nodes, '__iter__'):
            raise ValueError("Input `nodes` must be an iterable")
        key_to_node = {}
        order = []
        for entry in nodes:
            if not isinstance(entry, tuple) or len(entry) != 2:
                raise ValueError("Each entry must be a 2-element tuple")
            key_node, val_node = entry
            if not _is_scalar_node(key_node):
                raise ValueError("Key must be a ScalarNode")
            key_str = key_node.value
            if key_str not in key_to_node:
                key_to_node[key_str] = (key_node, val_node)
                order.append(key_str)
            else:
                existing_key, existing_val = key_to_node[key_str]
                merged_val = _merge_node_values(existing_val, val_node)
                key_to_node[key_str] = (existing_key, merged_val)
        # Build result list respecting original order
        result = [(key_to_node[k][0], key_to_node[k][1]) for k in order]
        return result
    except Exception as exc:
        raise ValueError(f"Error during deep merge: {exc}") from exc

