def bash_completion():
    """
    Return a bash completion script for the borgmatic command.  The script is generated by
    introspecting borgmatic's command‑line parsers.  If borgmatic or its parser cannot
    be imported, an empty string is returned.

    The returned script registers a completion function that suggests all top‑level
    sub‑commands of borgmatic.  It does not attempt to complete options or nested
    sub‑commands; it can be extended in the future.
    """
    import importlib
    import argparse

    try:
        mod = importlib.import_module("borgmatic")
    except Exception:
        # Borgmatic is not installed, or cannot be imported.
        return ""

    # Try to locate the root parser.  Borgmatic uses a function called build_parser
    # in borgmatic.cli to construct the argparse.ArgumentParser.
    try:
        parser = None
        if hasattr(mod, "cli"):
            cli = mod.cli
            if hasattr(cli, "build_parser"):
                # Some borgmatic releases may expose the function directly
                parser = cli.build_parser()
            elif hasattr(cli, "create_argument_parser"):
                parser = cli.create_argument_parser()
        if parser is None:
            return ""
    except Exception:
        return ""

    # Collect the names of top‑level sub‑commands.
    subcommands = []
    try:
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                subcommands.extend(action.choices.keys())
                break
    except Exception:
        return ""

    if not subcommands:
        return ""

    # Build a very small completion script.
    script = f"""__borgmatic_complete()
{{
    local cur prev words cword
    _get_comp_words_by_ref -n : cur prev words cword
    if [[ "$prev" == "borgmatic" && $cword -eq 1 ]]; then
        COMPREPLY=($(compgen -W "{" ".join(subcommands)}" -- "$cur"))
        return 0
    fi
}}
complete -F __borgmatic_complete borgmatic
"""
    return script

