def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation of inputs
    if not isinstance(number, int):
        raise TypeError(f"Expected 'number' to be int, got {type(number).__name__}")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("Alphabet must be a non-empty list of strings.")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols to form a number system.")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"Expected 'padding' to be int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("Padding cannot be negative.")

    negative = False
    if number < 0:
        negative = True
        number = -number

    # Convert number to string using the alphabet
    if number == 0:
        result_digits = [alphabet[0]]
    else:
        result_digits = []
        while number:
            number, r = divmod(number, base)
            result_digits.append(alphabet[r])
        result_digits.reverse()

    # Apply padding if requested
    if padding is not None:
        pad_len = padding - len(result_digits)
        if pad_len > 0:
            result_digits = [alphabet[0]] * pad_len + result_digits

    result = ''.join(result_digits)
    return '-' + result if negative else result

