    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two unique digits")

    # Map each character in the alphabet to its numeric value
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    if not string:
        raise ValueError("Input string must not be empty")

    # Handle optional negative sign
    negative = False
    if string[0] == '-':
        negative = True
        string = string[1:]
        if not string:
            raise ValueError("String cannot contain only a '-' sign")

    result = 0
    for ch in string:
        try:
            digit = char_to_value[ch]
        except KeyError:
            raise ValueError(f"Character '{ch}' not found in alphabet") from None
        result = result * base + digit

    return -result if negative else result

