    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError("s must be a string")

    # Determine platform value
    if platform == 'this':
        try:
            import sys
            platform_value = 0 if sys.platform.startswith('win') else 1
        except Exception:
            platform_value = 1
    else:
        try:
            platform_value = int(platform)
        except Exception:
            platform_value = 1

    tokens = []

    if platform_value == 1:  # POSIX
        i = 0
        length = len(s)
        while i < length:
            # Skip leading whitespace
            while i < length and s[i].isspace():
                i += 1
            if i >= length:
                break
            token = []
            in_quote = False
            quote_char = ''
            while i < length:
                c = s[i]
                if in_quote:
                    if c == quote_char:
                        in_quote = False
                        i += 1
                    elif c == '\\' and i + 1 < length:
                        i += 1
                        token.append(s[i])
                        i += 1
                    else:
                        token.append(c)
                        i += 1
                else:
                    if c.isspace():
                        break
                    elif c in ('"', "'"):
                        in_quote = True
                        quote_char = c
                        i += 1
                    elif c == '\\' and i + 1 < length:
                        i += 1
                        token.append(s[i])
                        i += 1
                    else:
                        token.append(c)
                        i += 1
            tokens.append(''.join(token))
    else:  # Windows
        i = 0
        length = len(s)
        while i < length:
            # Skip whitespace
            while i < length and s[i].isspace():
                i += 1
            if i >= length:
                break
            token = []
            quote = False
            while i < length:
                c = s[i]
                if not quote:
                    if c.isspace():
                        break
                    if c == '"':
                        quote = True
                        i += 1
                    else:
                        token.append(c)
                        i += 1
                else:
                    if c == '\\':
                        # Count consecutive backslashes
                        bs = 0
                        while i < length and s[i] == '\\':
                            bs += 1
                            i += 1
                        if i < length and s[i] == '"':
                            # backslashes before a quote
                            token.extend(['\\'] * (bs // 2))
                            if bs % 2 == 1:
                                token.append('"')
                            i += 1
                        else:
                            token.extend(['\\'] * bs)
                    elif c == '"':
                        quote = False
                        i += 1
                    else:
                        token.append(c)
                        i += 1
            tokens.append(''.join(token))

    return tokens

