def addignored(ignored):
    """
    Use the git command to obtain the file names, turn it into a list,
    sort the list for only ignored files, and return those files as a
    single string with each filename separated by a comma.
    """
    try:
        cmd = ["git", "ls-files", "-i", "-o", "--exclude-standard"]
        # If a path is provided, run git in that directory
        if ignored:
            output = subprocess.check_output(cmd, cwd=ignored, text=True)
        else:
            output = subprocess.check_output(cmd, text=True)
        files = [line.strip() for line in output.splitlines() if line.strip()]
        files.sort()
        return ",".join(files)
    except (subprocess.CalledProcessError, FileNotFoundError, OSError):
        # Return an empty string if git command fails or repository not found
        return ""

