def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import os, sys
    if not callable(func):
        raise TypeError("func must be a callable")
    if not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")
    module = func.__module__
    name = func.__name__
    # Construct the command that imports the function and calls it with any
    # additional arguments passed on the command line.
    py_code = f"import sys; import {module}; {name}(*sys.argv[1:])"
    cmd = [sys.executable, "-c", py_code] + list(args)
    # Build the environment for the subprocess.
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)
    try:
        return subprocess.run(cmd, timeout=timeout, env=env, check=True)
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(f"Subprocess timed out after {timeout} seconds") from exc
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Subprocess returned non-zero exit status {exc.returncode}") from exc

