def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("image_href must be a non-empty string")

    # Parse the URL
    try:
        parts = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid URL: {image_href}") from exc

    scheme = parts.scheme.lower()
    if scheme not in ("http", "https", "file"):
        raise ValueError(f"Unsupported URL scheme: {scheme}")

    netloc = parts.netloc
    if scheme != "file" and not netloc:
        raise ValueError("URL missing netloc (host)")

    # Determine image ID
    image_id = ""
    if parts.path:
        image_id = parts.path.rsplit("/", 1)[-1]
    if not image_id and parts.query:
        # Try to get an 'id' query parameter
        qs = urllib.parse.parse_qs(parts.query)
        if "id" in qs and qs["id"]:
            image_id = qs["id"][0]

    if not image_id:
        raise ValueError("Cannot determine image identifier from the URL")

    use_ssl = scheme == "https"
    return (image_id, netloc, use_ssl)

