def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        # Normalize commands
        if isinstance(commands, str):
            cmd = [commands]
        elif isinstance(commands, (list, tuple)):
            cmd = list(commands)
        else:
            raise TypeError(f"'commands' must be a string or a sequence, got {type(commands).__name__}")

        # Normalize args
        if args is None:
            args_list = []
        elif isinstance(args, str):
            args_list = [args]
        elif isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            raise TypeError(f"'args' must be a string or a sequence, got {type(args).__name__}")

        cmd.extend(args_list)

        if verbose:
            print(f"Running command: {' '.join(cmd)}")

        stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=False
        )

        if verbose:
            if result.stdout:
                print(f"stdout:\n{result.stdout}")
            if result.stderr:
                print(f"stderr:\n{result.stderr}")

        if result.returncode != 0:
            raise RuntimeError(
                f"Command '{' '.join(cmd)}' exited with {result.returncode}\n"
                f"stdout: {result.stdout}\n"
                f"stderr: {result.stderr}"
            )

        return result.stdout
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {commands}") from e
    except subprocess.SubprocessError as e:
        raise RuntimeError(f"Subprocess error: {e}") from e
    except TypeError as e:
        raise RuntimeError(f"Invalid input: {e}") from e

