def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper_cls = yaml.SafeDumper
    else:
        dumper_cls = dumper
    try:
        data = yaml.dump(obj, Dumper=dumper_cls, default_flow_style=False)
    except Exception as exc:
        raise ValueError("Error dumping object to YAML string") from exc
    # On Python 2, yaml.dump returns a byte string; decode to unicode
    try:
        return data.decode('utf-8')
    except AttributeError:
        # On Python 3, data is already a str
        return data

