            record = logging.LogRecord('load_configurations', logging.ERROR,
                                       filename, 0, msg, (), None)
            error_logs.append(record)
            continue

        if not isinstance(config, dict):
            msg = f'Parsed configuration from file "{filename}" is not a dictionary.'
            record = logging.LogRecord('load_configurations', logging.ERROR,
                                       filename, 0, msg, (), None)
            error_logs.append(record)
            continue

        if overrides:
            try:
                merge_dicts(config, overrides)
            except Exception as e_override:
                msg = f'Failed to apply overrides to file "{filename}": {e_override}'
                record = logging.LogRecord('load_configurations', logging.ERROR,
                                           filename, 0, msg, (), None)
                error_logs.append(record)
                continue

        if resolve_env:
            try:
                config = replace_env_vars(config)
            except Exception as e_env:
                msg = f'Failed to resolve environment variables in file "{filename}": {e_env}'
                record = logging.LogRecord('load_configurations', logging.ERROR,
                                           filename, 0, msg, (), None)
                error_logs.append(record)
                continue

        configs[filename] = config

    return configs, error_logs

