                # Unexpected type for handlers; raise a runtime error.
                raise RuntimeError("Failed to copy protocol handlers") from exc

        # Validate input type.
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                "protocol_version must be a tuple, e.g. (3, 5), not "
                f"{type(protocol_version).__name__}"
            )

        # Return the handler for the requested version if it exists.
        try:
            handler = handlers[protocol_version]
            return {protocol_version: handler}
        except KeyError:
            # No such protocol version available; return an empty dict.
            return {}
        except Exception as exc:
            # Any other unexpected issue is surfaced as a runtime error.
            raise RuntimeError("Unexpected error while retrieving protocol handlers") from exc

