def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a histogram-like object to a simple graph representation.
    The function makes minimal assumptions about the structure of ``hist``:
    it must expose the bin edges and the bin contents.  The resulting
    graph is returned as a plain dictionary containing the list of
    points, the field names and an optional ``scale`` entry.

    Parameters
    ----------
    hist : object
        Histogram-like object providing bin edges and contents.
    make_value : function, optional
        Function receiving a single bin content and returning a tuple or
        list of values that will be stored as graph coordinates after
        the coordinate value defined by ``get_coordinate``.
    get_coordinate : {"left", "right", "middle"}, default "left"
        Which bin coordinate to use for the x‑axis of the graph.
    field_names : tuple, default ("x", "y")
        Names of the fields for the returned graph points.  The first
        name corresponds to the coordinate chosen by ``get_coordinate``;
        subsequent names correspond to elements returned by ``make_value``
        (or to the single bin value if ``make_value`` is None).
    scale : bool or any, optional
        If ``True`` will attempt to use ``hist.scale`` if it exists;
        otherwise it is stored literally as the ``scale`` value.

    Returns
    -------
    dict
        Dictionary with keys ``"field_names"``, ``"data"``, and optionally
        ``"scale"`` containing the graph representation.
    """
    # Validate parameters
    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")
    if not isinstance(field_names, (tuple, list)) or len(field_names) < 2:
        raise ValueError("field_names must be a sequence with at least two entries")

    # Extract bin edges
    if hasattr(hist, "edges"):
        edges = hist.edges
    elif hasattr(hist, "bin_edges"):
        edges = hist.bin_edges
    else:
        raise AttributeError("hist does not provide bin edges (e.g., 'edges' or 'bin_edges')")

    # Extract bin contents
    if hasattr(hist, "contents"):
        contents = hist.contents
    elif hasattr(hist, "bin_contents"):
        contents = hist.bin_contents
    elif hasattr(hist, "data"):
        contents = hist.data
    else:
        raise AttributeError("hist does not provide bin contents (e.g., 'contents', 'bin_contents', or 'data')")

    if len(edges) != len(contents) + 1:
        raise ValueError("Number of edges must be one more than number of contents")

    # Determine scale
    if scale is True:
        if hasattr(hist, "scale"):
            scale_value = hist.scale
        else:
            scale_value = None
    else:
        scale_value = scale

    points = []
    for i in range(len(contents)):
        if get_coordinate == "left":
            coord = edges[i]
        elif get_coordinate == "right":
            coord = edges[i + 1]
        else:  # middle
            coord = (edges[i] + edges[i + 1]) / 2.0

        bin_value = contents[i]
        try:
            if make_value is None:
                val = bin_value
            else:
                val = make_value(bin_value)
        except Exception as e:
            raise ValueError(f"make_value failed on bin {i}: {e}") from e

        # Normalize val to a tuple/list
        if isinstance(val, (tuple, list)):
            vals = tuple(val)
        else:
            vals = (val,)

        if len(vals) != len(field_names) - 1:
            raise ValueError(
                f"make_value returned {len(vals)} values; expected {len(field_names)-1}"
            )

        point = (coord, *vals)
        points.append(point)

    result = {"field_names": tuple(field_names), "data": points}
    if scale_value is not None:
        result["scale"] = scale_value
    return result

