def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Helper for importing modules without an import statement
    _inspect = __import__('inspect')
    _zope = __import__('zope.interface')
    Invalid = getattr(_zope, 'Invalid', Exception)

    errors = []
    # Step 1: check providedBy if not tentative
    try:
        if not tentative:
            try:
                provides = iface.providedBy(candidate)
            except AttributeError:
                # Some interface objects expose `provides` directly
                provides = getattr(candidate, 'provides', None)
            if not provides:
                errors.append(f"{candidate!r} does not provide {iface}")
    except Exception as exc:
        errors.append(f"Error checking providedBy for {candidate!r}: {exc}")

    # Helper to get required methods and attributes
    def _collect_requirements(iface_obj):
        # Zope interface provides these attributes in various names
        req_attrs = getattr(iface_obj, 'requiredAttributes', None)
        if req_attrs is None:
            req_attrs = getattr(iface_obj, '_required_attrs', None)
        if req_attrs is None:
            req_attrs = getattr(iface_obj, '_required_attributes', {})
            if not isinstance(req_attrs, dict):
                req_attrs = {}
        req_methods = getattr(iface_obj, 'requiredMethods', None)
        if req_methods is None:
            req_methods = getattr(iface_obj, '_required_methods', None)
        if req_methods is None:
            req_methods = getattr(iface_obj, '_required_methods', {})
            if not isinstance(req_methods, dict):
                req_methods = {}
        # Some interface implementations expose only a set of names; transform accordingly
        method_names = set()
        if isinstance(req_methods, dict):
            method_names = set(req_methods.keys())
        else:
            method_names = set(req_methods)  # assume iterable of names
        attr_names = set()
        if isinstance(req_attrs, dict):
            attr_names = set(req_attrs.keys())
        else:
            attr_names = set(req_attrs)
        return method_names, attr_names

    try:
        req_methods, req_attrs = _collect_requirements(iface)
    except Exception as exc:
        errors.append(f"Error collecting interface requirements: {exc}")
        req_methods, req_attrs = set(), set()

    # Verify methods
    for name in req_methods:
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} missing required method {name!r}")
            continue
        method = getattr(candidate, name)
        if not callable(method):
            errors.append(f"{candidate!r} has non-callable attribute {name!r}")
            continue
        # attempt signature comparison if possible
        try:
            expected = getattr(iface, name, None)
            if expected is not None:
                expected_sig = _inspect.signature(expected)
                actual_sig = _inspect.signature(method)
                if expected_sig.parameters != actual_sig.parameters:
                    errors.append(
                        f"Signature mismatch for method {name!r} "
                        f"in {candidate!r}: expected {expected_sig} "
                        f"got {actual_sig}"
                    )
        except Exception:
            # If signature cannot be compared, skip
            pass

    # Verify attributes
    for name in req_attrs:
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} missing required attribute {name!r}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0]) from None
        else:
            # Combine messages meaningfully
            joined = '; '.join(errors) + f" (vtype={vtype})"
            raise Invalid(joined) from None

    return True

