    def get_candidate_signature(name):
        try:
            attr = getattr(candidate, name)
        except AttributeError:
            return None, None
        if _compat.is_callable(attr):
            try:
                return attr, inspect.signature(attr)
            except Exception:
                return attr, None
        return None, None

