    #   Note: interface may declare methods starting with 'def'
    #   and attributes as typed fields.
    #   We'll use standard zope.interface introspection helpers.
    try:
        # Use the interface property getAllMembers
        interface_names = list(iface.getRequiredAttributeNames() or [])
        interface_names += list(iface.getRequiredMethodNames() or [])
    except Exception:
        # Fallback: use the interface's __dict__
        interface_names = []
        for name, value in iface.__dict__.items():
            if name.startswith('_'):
                continue
            interface_names.append(name)

    # 3. Separate methods and attributes from interface
    interface_methods = {}
    interface_attributes = []

    for name in interface_names:
        member = getattr(iface, name, None)
