def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function accepts a datetime instance (timezone-aware or naive),
    an integer timestamp, or an ISO‑8601 string representation of a
    datetime.  The output is a UTC ISO‑8601 string without
    micro‑seconds: ``YYYY-MM-DDTHH:MM:SSZ``.

    Parameters
    ----------
    dt : datetime.datetime | int | str
        The datetime to format.  If a string is supplied it must be
        parseable by ``datetime.fromisoformat`` or contain a UNIX
        timestamp.  An integer is treated as a UNIX timestamp in
        seconds.

    Returns
    -------
    str
        The formatted UTC datetime string.

    Raises
    ------
    TypeError
        If the input type cannot be interpreted as a datetime.
    ValueError
        If the input cannot be parsed into a datetime.
    """
    from datetime import datetime, timezone, timedelta

    # Helper to return ISO‑8601 UTC format without microseconds
    def _to_utc_iso(dt_obj: datetime) -> str:
        if dt_obj.tzinfo is None:
            # Assume naive datetime is already in UTC
            utc_dt = dt_obj.replace(tzinfo=timezone.utc)
        else:
            utc_dt = dt_obj.astimezone(timezone.utc)
        return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    if dt is None:
        raise ValueError("datetime argument cannot be None")

    # If datetime instance
    if isinstance(dt, datetime):
        return _to_utc_iso(dt)

    # If integer or float: interpret as Unix timestamp
    if isinstance(dt, (int, float)):
        try:
            # Convert to datetime in UTC
            utc_dt = datetime.fromtimestamp(dt, tz=timezone.utc)
        except (OSError, OverflowError, ValueError) as exc:
            raise ValueError(f"cannot interpret timestamp {dt!r}") from exc
        return _to_utc_iso(utc_dt)

    # If string: try ISO parse or numeric string
    if isinstance(dt, str):
        # Try numeric string (timestamp)
        try:
            ts = float(dt)
            utc_dt = datetime.fromtimestamp(ts, tz=timezone.utc)
            return _to_utc_iso(utc_dt)
        except ValueError:
            pass

        # Try ISO 8601 parse
        try:
            # Python 3.7+ supports fromisoformat for ISO strings
            dt_obj = datetime.fromisoformat(dt)
        except AttributeError:
            # fallback: use strptime
            try:
                dt_obj = datetime.strptime(dt, "%Y-%m-%dT%H:%M:%S")
            except Exception:
                raise ValueError(f"cannot parse datetime string {dt!r}")
        # If parsed, format
        return _to_utc_iso(dt_obj)

    raise TypeError(f"Unsupported type for format_dt: {type(dt).__name__}")

