def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """
    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the
    result of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    # Validate replacer if provided
    if replacer is not None and not callable(replacer):
        raise TypeError("replacer must be a callable")

    tags_set: Set[str] = set()
    result_lines = []
    inside_code = False

    tag_regex = re.compile(r'(?<!\w)#([A-Za-z0-9_]+)')

    for line in text.splitlines(keepends=True):
        stripped = line.lstrip()
        # Toggle code block state when encountering a fence (e.g., ```)
        if stripped.startswith("```"):
            inside_code = not inside_code
            result_lines.append(line)
            continue

        if not inside_code:
            # Find tags
            for match in tag_regex.finditer(line):
                tag_word = match.group(1)
                tags_set.add(tag_word)

            # Replace tags if replacer is provided
            if replacer is not None:
                def _replace(m: re.Match) -> str:
                    original_tag = m.group(1)
                    try:
                        replacement = replacer(original_tag)
                    except Exception:
                        # If replacer fails, keep the original tag
                        return m.group(0)
                    if not isinstance(replacement, str):
                        # Ensure replacement is a string; otherwise keep original
                        return m.group(0)
                    return f"#{replacement}"
                new_line = tag_regex.sub(_replace, line)
            else:
                new_line = line
        else:
            new_line = line

        result_lines.append(new_line)

    final_text = "".join(result_lines)
    return tags_set, final_text

