def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("Expected a string")
    import re

    # Step 1: Add target and rel attributes to existing <a> tags
    def _add_attrs(match):
        tag = match.group(0)
        # Extract attributes
        attrs = re.findall(r'(\w+)(?:\s*=\s*(".*?"|\'.*?\'|[^>\s]+))?', tag)
        attr_dict = {}
        for name, value in attrs:
            if name.lower() == 'href':
                attr_dict[name] = value.strip('"\'')
            else:
                attr_dict[name] = value.strip('"\'') if value else None
        # Ensure target and rel
        if 'target' not in attr_dict:
            attr_dict['target'] = '_blank'
        if 'rel' not in attr_dict:
            attr_dict['rel'] = 'noopener noreferrer'
        # Rebuild opening tag
        parts = ['<a']
        for key, val in attr_dict.items():
            if val is None:
                parts.append(f'{key}')
            else:
                parts.append(f'{key}="{val}"')
        parts.append('>')
        return ''.join(parts)

    text = re.sub(r'<a\b[^>]*>', _add_attrs, text, flags=re.IGNORECASE)

    # Step 2: Split into anchor and non-anchor parts
    parts = re.split(r'(<a\b[^>]*>.*?</a>)', text, flags=re.IGNORECASE | re.DOTALL)

    # URL pattern
    url_pattern = r'(?P<url>(?:https?://|www\.)[^\s<>"\'\]\)]+)'

    def _replace_url(match):
        url = match.group('url')
        href = url if url.startswith(('http://', 'https://')) else 'http://' + url
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'

    processed = []
    for part in parts:
        if re.match(r'(?i)^<a\b', part):
            processed.append(part)
        else:
            processed.append(re.sub(url_pattern, _replace_url, part))
    return ''.join(processed)

