def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1', 'key2')

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain

    :return: the modified dictionary
    """
    # Validate inputs
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dict")
    if key is None:
        raise ValueError("key cannot be None")
    # Handle the case where key is a sequence of keys (e.g., from split('.'))
    # If key is a tuple or list and *keys is empty, treat key as the full key chain.
    if isinstance(key, (list, tuple)) and not keys:
        full_keys = list(key)
    else:
        full_keys = [key] + list(keys)
    if not full_keys:
        raise ValueError("At least one key must be provided")
    # Traverse or build nested dictionaries
    current = dic
    for i, k in enumerate(full_keys):
        if i == len(full_keys) - 1:
            # Last key: assign value
            current[k] = val
        else:
            # For intermediate keys, ensure dict exists
            if k not in current:
                current[k] = {}
            elif not isinstance(current[k], dict):
