def _include_groups(self, parser_dict):
    """
    Resolve the include dict directive in the spec files.  The directive
    is expected to be a ``_include`` key whose value is a mapping from
    group names to a relative or absolute file path containing the
    group definition.  The referenced files are parsed as YAML and the
    resulting dictionaries are inserted into *parser_dict* under the
    corresponding group keys.  Recursive includes are supported.
    """
    import yaml
    from pathlib import Path

    def _resolve(node: dict, base_path: Path):
        if not isinstance(node, dict):
            return

        keys_to_process = [k for k, v in node.items() if k == "_include"]
        for key in keys_to_process:
            include_map = node.pop(key)
            if not isinstance(include_map, dict):
                raise ValueError(f"Expected a mapping for '_include', got {type(include_map).__name__}")

            for group_name, rel_path in include_map.items():
                include_path = (base_path / rel_path).resolve()
                if not include_path.is_file():
                    raise FileNotFoundError(f"Included file not found: {include_path}")

                try:
                    with include_path.open("r", encoding="utf-8") as fh:
                        content = yaml.safe_load(fh)
                except Exception as exc:
                    raise ValueError(f"Failed to parse included file {include_path}: {exc}") from exc

                if not isinstance(content, dict):
                    raise ValueError(f"Included file {include_path} must contain a mapping at the top level")

                # Merge the included content; if the group_name already exists, we replace it
                node[group_name] = content
                # Recursively resolve any includes inside the freshly loaded group
                _resolve(content, include_path.parent)

        # Process nested dictionaries
        for value in list(node.values()):
            if isinstance(value, dict):
                _resolve(value, base_path)
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
                        _resolve(item, base_path)

    # Determine the base directory.  If the object has an attribute that indicates the source file,
    # prefer that; otherwise default to the current working directory.
    base_path = getattr(self, "source_file_path", Path.cwd())
    if isinstance(base_path, str):
        base_path = Path(base_path)

    _resolve(parser_dict, base_path)
    return parser_dict

