def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    This method expects ``parser_dict`` to be a mapping that may contain an
    ``"include"`` key whose value is either a string or a list of group names.
    For each group name it retrieves the corresponding group definition from
    ``self._group_definitions`` (if present) and merges those definitions
    into a single dictionary.  Keys from later groups overwrite earlier ones.

    The returned dictionary contains the merged group definitions.  If no
    ``"include"`` key is present an empty dictionary is returned.

    Raises
    ------
    TypeError
        If ``parser_dict`` is not a mapping.
    ValueError
        If the value of the ``"include"`` key is neither a string nor a list
        of strings.
    KeyError
        If a requested group name is not found in ``self._group_definitions``.
    """
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary")

    inclusion = parser_dict.get("include")
    if inclusion is None:
        return {}

    # Normalize to list of strings
    if isinstance(inclusion, str):
        group_names = [inclusion]
    elif isinstance(inclusion, (list, tuple)):
        group_names = inclusion
        if not all(isinstance(name, str) for name in group_names):
            raise ValueError(
                "all items in 'include' list must be strings representing group names"
            )
    else:
        raise ValueError(
            "'include' must be a string or a list/tuple of strings"
        )

    merged = {}
    for name in group_names:
        try:
            group = self._group_definitions[name]
        except (AttributeError, KeyError):
            raise KeyError(f"Group '{name}' not found in self._group_definitions")
        if not isinstance(group, dict):
            raise ValueError(f"Group '{name}' must be a dictionary")
        merged.update(group)
    return merged

