     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    # Build command
    cmd = ['ansible-playbook']
    if isinstance(playbook_path, (list, tuple)):
        cmd.extend(str(p) for p in playbook_path)
    else:
        cmd.append(str(playbook_path))

    # Verbosity
    if verbose is not None:
        try:
            lvl = int(verbose)
            if lvl > 0:
                cmd.append('-' + 'v' * lvl)
        except ValueError:
            # accept string like "vvv"
            cmd.append('-' + str(verbose))

    # Extra vars
    if extra_vars:
        try:
            # Convert dict to json string
            json_str = json.dumps(extra_vars, separators=(',', ':'))
            cmd.extend(['--extra-vars', json_str])
        except Exception as exc:
            raise ValueError("Failed to serialize extra_vars to JSON") from exc

    # Additional ansible arguments
    if ansible_args:
        for key, val in ansible_args.items():
            if val is None:
                continue
            # If key already prefixed with dash, use directly
            if isinstance(key, str) and key.startswith('-'):
                opt = key
            else:
                opt = f"--{key}" if not key.startswith('--') else key
            # For boolean flags, include only if True
            if isinstance(val, bool):
                if val:
                    cmd.append(opt)
                continue
            # For list values, join with commas
            if isinstance(val, (list, tuple)):
                val = ','.join(str(x) for x in val)
            cmd.extend([opt, str(val)])

    # Determine working directory if workspace provides a 'path' attribute
    cwd = None
    try:
        cwd = getattr(ir_workspace, "path")
    except Exception:
        pass

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            check=True,
            capture_output=True,
            text=True
        )
        # Return the completed process so callers can inspect stdout/stderr/returncode
        return result
    except FileNotFoundError as e:
        raise RuntimeError("The 'ansible-playbook' command was not found in PATH.") from e
    except subprocess.CalledProcessError as e:
        msg = (
            f"ansible-playbook failed with exit code {e.returncode}\n"
            f"Command: {' '.join(e.cmd)}\n"
            f"Stdout: {e.stdout}\n"
            f"Stderr: {e.stderr}"
        )
        raise RuntimeError(msg) from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error while running ansible-playbook: {e}") from e

