        """
        Casts string arguments to their intended types based on a predefined schema for each parser.
        The input dictionary is modified in-place and also returned for convenience.

        Parameters
        ----------
        parser_name : str
            Name of the command parser (e.g., "main", "virsh", "ospd").
        values_dict : dict
            Dictionary containing argument names mapped to their string values.

        Returns
        -------
        dict
            The same dictionary with values cast to appropriate Python types.
        """
        # Define a minimal schema mapping for known parsers.
        # In a real implementation this would be imported from a config file or defined elsewhere.
        _parser_type_map = {
            "main": {
                "count": int,
                "verbose": bool,
                "names": list,
                "ratio": float,
            },
            "virsh": {
                "threads": int,
                "force": bool,
                "paths": list,
            },
            "ospd": {
                "port": int,
                "enabled": bool,
                "tags": list,
            },
        }

        # Helper to convert a string to a boolean.
        def _str_to_bool(val):
            if isinstance(val, bool):
                return val
            if isinstance(val, (int, float)):
                return bool(val)
            if not isinstance(val, str):
                raise ValueError(f"Cannot convert type {type(val)} to bool")
            val_l = val.strip().lower()
            if val_l in ("true", "1", "yes", "y", "t"):
                return True
            if val_l in ("false", "0", "no", "n", "f"):
                return False
            raise ValueError(f"Invalid boolean string: {val}")

        # Helper to interpret a string that could be a list.
        def _parse_list(val):
            if isinstance(val, list):
                return val
            if not isinstance(val, str):
                raise ValueError(f"Cannot parse list from type {type(val)}")
            val = val.strip()
            # Try literal eval if looks like a list literal.
            if (val.startswith('[') and val.endswith(']')):
                try:
                    import ast
                    parsed = ast.literal_eval(val)
                    if isinstance(parsed, list):
                        return parsed
                except Exception:
                    pass
            # Fallback: split by commas.
            return [item.strip() for item in val.split(',') if item.strip()]

        # Determine the type mapping for this parser.
        type_map = _parser_type_map.get(parser_name, {})
        for key, raw_val in list(values_dict.items()):
            target_type = type_map.get(key)
            if not target_type:
                # No casting rule defined for this key; leave as-is.
                continue
            try:
                if target_type is bool:
                    new_val = _str_to_bool(raw_val)
                elif target_type is int:
                    new_val = int(raw_val)
                elif target_type is float:
                    new_val = float(raw_val)
                elif target_type is list:
                    new_val = _parse_list(raw_val)
                else:
                    # Generic conversion using the type constructor.
                    new_val = target_type(raw_val)
                values_dict[key] = new_val
            except Exception:
                # If conversion fails, keep the original value and possibly log.
                # In this environment we simply ignore the error.
                pass

        return values_dict

