        raise ValueError("Root cannot be empty")
    if not path:
        raise ValueError("Path cannot be empty")

    # If the path is exactly the root, return an empty string
    if path == root:
        return ''

    # Attempt to find the root at the start of the path
    if path.startswith(root):
        remainder = path[len(root):]
    else:
        # Consider typical path separators
        separators = ('/', '\\')
        matched = False
        for sep in separators:
            prefix = root + sep
            if path.startswith(prefix):
                remainder = path[len(prefix):]
                matched = True
                break
        if not matched:
            raise ValueError(f"Path '{path}' does not start with the specified root '{root}'.")

    # Strip any leading separators from the remainder
    while remainder and remainder[0] in ('/', '\\'):
        remainder = remainder[1:]

    return remainder

